import SwiftUI

/// The Strata mark: a blocky S, cut from a rounded square.
///
/// Two bars and a slash, in the same geometry the tower is built from — the
/// outer corners take `BlockSurface`'s own 14.7% radius and the interior
/// angles take about half of it.
///
/// **Kept, but not the mark.** It held the job for a day. The argument for it
/// was that a light monoline disappears at 44pt in Settings and at 50pt on a
/// home screen where a solid form holds; the owner's answer is that the logo
/// is the drawn `S`, and that is the call. The shape stays because it is
/// generated by `tools/make_logo.py`, costs nothing, and the small-size
/// question is a real one that may come back.
struct StrataMarkShape: Shape {
    func path(in rect: CGRect) -> Path {
        let side = min(rect.width, rect.height)
        let pts = StrataMarkShape.outline.map {
            CGPoint(x: rect.minX + $0.x * side, y: rect.minY + $0.y * side)
        }

        var path = Path()
        var started = false
        for (i, p) in pts.enumerated() {
            let prev = pts[(i - 1 + pts.count) % pts.count]
            let next = pts[(i + 1) % pts.count]
            let radius = Self.radius(at: i, point: p, prev: prev, next: next, side: side)
            guard radius > 0 else {
                if started { path.addLine(to: p) } else { path.move(to: p); started = true }
                continue
            }
            // Trim back along both edges, then round between them. The same
            // quadratic the generator samples, so the Swift shape, the SVGs
            // and the app icon are one drawing.
            func stepped(_ from: CGPoint, toward: CGPoint) -> CGPoint {
                let dx = toward.x - from.x, dy = toward.y - from.y
                let d = max(hypot(dx, dy), 0.0001)
                return CGPoint(x: from.x + dx / d * radius, y: from.y + dy / d * radius)
            }
            let a = stepped(p, toward: prev)
            let b = stepped(p, toward: next)
            if started { path.addLine(to: a) } else { path.move(to: a); started = true }
            path.addQuadCurve(to: b, control: p)
        }
        path.closeSubpath()
        return path
    }

    /// The radius a corner can actually take.
    ///
    /// Trimming back by more than half of either adjacent edge turns the
    /// corner inside out, and the slash meets the bars at a very acute angle —
    /// this clamp is what lets the interior corners round at all.
    private static func radius(at index: Int, point: CGPoint,
                               prev: CGPoint, next: CGPoint, side: CGFloat) -> CGFloat {
        let wanted = cornerRadii[index] * side
        let a = hypot(point.x - prev.x, point.y - prev.y)
        let b = hypot(point.x - next.x, point.y - next.y)
        return min(wanted, a * 0.5, b * 0.5)
    }

    // Generated by tools/make_logo.py --swift. Do not hand-edit.
    /// The mark's outline in a unit square, y DOWN.
    static let outline: [CGPoint] = [
        CGPoint(x: 0.0000, y: 0.0000), CGPoint(x: 1.0000, y: 0.0000), CGPoint(x: 1.0000, y: 0.3000),
        CGPoint(x: 0.5600, y: 0.3000), CGPoint(x: 1.0000, y: 0.7000), CGPoint(x: 1.0000, y: 1.0000),
        CGPoint(x: 0.0000, y: 1.0000), CGPoint(x: 0.0000, y: 0.7000), CGPoint(x: 0.4400, y: 0.7000),
        CGPoint(x: 0.0000, y: 0.3000)
    ]
    /// One wanted radius per vertex, as a fraction of the side.
    /// The outer corners take the block's ratio; the interior
    /// angles take a smaller one, so the counters read as cut
    /// rather than as knife points.
    static let cornerRadii: [CGFloat] = [
        0.1470, 0.1470, 0.0750, 0.0750, 0.0750,
        0.1470, 0.1470, 0.0750, 0.0750, 0.0750
    ]
}

// MARK: - Drawn lettering

/// A word the owner drew, as a vector asset.
///
/// The three of them — `Strata`, the single `S`, and `Memories` — are one
/// typeface and one mechanism, so they are one view. Each is an SVG in the
/// asset catalogue with `preserves-vector-representation` and
/// `template-rendering-intent: template`, which means the app carries the
/// drawing rather than a bitmap of it: it is resolution-independent at any
/// size and `color` tints it exactly the way it tinted a `Text`.
///
/// **`size` is CAP HEIGHT, not point size.** These drawings have no ascender
/// and no descender — the artboard is the cap — so the frame's top IS the top
/// of the ink. That is why a header made of one takes
/// `GridConstants.headerArtworkTopPadding` and not the version that corrects
/// for where a font sets its cap inside its own box.
///
/// **It scales with Dynamic Type**, which is the one thing artwork usually
/// gives up. `@ScaledMetric` grows the cap height from the same text style the
/// system title would have used — and because the frame's top is the cap top,
/// growing it pushes ink DOWN from a fixed line rather than moving the line,
/// so a larger accessibility size does not drag the header off its rule.
private struct DrawnLettering: View {
    let asset: String
    /// The drawing's own proportions, width over height, from its viewBox.
    let aspect: CGFloat
    let color: Color
    let label: String
    @ScaledMetric private var size: CGFloat

    init(asset: String, aspect: CGFloat, size: CGFloat, color: Color,
         label: String, relativeTo style: Font.TextStyle) {
        self.asset = asset
        self.aspect = aspect
        self.color = color
        self.label = label
        self._size = ScaledMetric(wrappedValue: size, relativeTo: style)
    }

    var body: some View {
        Image(asset)
            .renderingMode(.template)
            .resizable()
            .scaledToFit()
            .frame(width: size * aspect, height: size)
            .foregroundStyle(color)
            .accessibilityLabel(label)
    }
}

/// The app's name, as the owner's own letterforms.
///
/// **Why this and not Jaro.** Jaro is a heavy angular slab; this is a wide,
/// light, squared-off monoline with rounded corners — the same move the block
/// makes, a rectangle with its corners softened, which is what "clean but
/// structured" actually looks like in a letterform. It is also more than twice
/// the width at the same cap height, so a header made of it is a band across
/// the top rather than a mark in the corner. That is deliberate, and it is why
/// the camera's size had to come down: see `CameraView.Header`.
struct StrataWordmark: View {
    /// Cap height.
    var size: CGFloat = 28
    var color: Color = .primary

    /// From the drawing's viewBox: 182 x 28.
    static let aspect: CGFloat = 182.0 / 28.0

    var body: some View {
        DrawnLettering(asset: "StrataWordmark", aspect: Self.aspect, size: size,
                       color: color, label: "Strata", relativeTo: .largeTitle)
    }
}

/// The Memories screen's title, in the same hand.
///
/// A drawing rather than a `Text` for the same reason the app's name is one:
/// this is the one word the screen is named after, and the owner drew the
/// face. Everything else on the page stays on SF Pro Rounded — a section
/// label or a month name set in a display face stops being a label.
struct MemoriesTitle: View {
    /// Cap height, matched to what the screen-title font actually sets — see
    /// `Typography.screenTitleCap`. Not `screenTitleSize`: that is an em, and
    /// using it made this title half again as tall as the tower's.
    var size: CGFloat = Typography.screenTitleCap
    var color: Color = .primary

    /// From the drawing's viewBox: 216 x 28.
    static let aspect: CGFloat = 216.0 / 28.0

    var body: some View {
        DrawnLettering(asset: "MemoriesTitle", aspect: Self.aspect, size: size,
                       color: color, label: "Memories", relativeTo: .largeTitle)
    }
}

/// "win" / "wins", the word under the tower's count, in the same hand.
///
/// It was SF Pro Rounded at a subheadline size, which made the header two
/// faces at two sizes to say one thing. It is now the same drawing the count
/// is, on the same 28-unit body, so the pair reads as one object.
///
/// **The singular is cut from the plural**, by `tools/make_win_singular.py`,
/// which drops the rightmost of the five contours. Asking for a second export
/// would have risked two drawings that only nearly match; this way they are
/// literally the same letterforms, and the sidebearing is the one the export
/// already had.
///
/// `size` is the drawing's whole body, so handing it
/// `Typography.screenTitleCap` puts the `i`'s dot on the numeral's cap line
/// and its x-height at 21.02/28 of that — which is what lowercase beside
/// figures is supposed to do, rather than a size anybody picked.
struct WinsWord: View {
    let count: Int
    var size: CGFloat = Typography.screenTitleCap
    var color: Color = .primary.opacity(0.35)

    /// From the drawings' viewBoxes: 132 x 28 and 98.87 x 28.
    static let pluralAspect: CGFloat = 132.0 / 28.0
    static let singularAspect: CGFloat = 98.87 / 28.0

    private var isPlural: Bool { count != 1 }

    var body: some View {
        DrawnLettering(asset: isPlural ? "WinsWord" : "WinWord",
                       aspect: isPlural ? Self.pluralAspect : Self.singularAspect,
                       size: size, color: color,
                       label: isPlural ? "wins" : "win",
                       relativeTo: .largeTitle)
            // The ink runs to the bottom of the body, so the drawing's bottom
            // IS its baseline — which lets it sit on the numeral's real one.
            .alignmentGuide(.firstTextBaseline) { $0[.bottom] }
    }
}

// MARK: - The mark

/// The app's mark: the owner's `S`, knocked out of one of the app's blocks.
///
/// The same drawing as the wordmark's first letter, so the icon, the Settings
/// header and the camera all show one letterform rather than three things
/// that resemble each other.
///
/// **It is a block, and that is the whole idea.** A bare pink S on the page
/// was the mark for a day and it was thin — a light monoline has nothing to
/// hold at 44pt, and it shared no material with anything else in the app. On
/// a block it does: `BlockSurface` gives it the rim brightest along the top
/// edge and the frosted band across the bottom, which is the one texture this
/// app is made of. The letter sits on it in white, which is what the mark was
/// before the S existed — a single pink block with a white letter on it.
struct StrataMark: View {
    /// The block's side. The letter is sized off it.
    var side: CGFloat = 44

    /// How much of the block's side the letter's cap takes.
    ///
    /// 0.46 rather than a tighter fit. The `S` is 33 wide to 28 tall, so at
    /// 0.46 it sets 24pt across a 44pt block — a little over half the width,
    /// which leaves the block reading as a block. Past about 0.55 the letter
    /// starts to touch the rim and the two stop being separate objects.
    private static let capRatio: CGFloat = 0.46
    private static let aspect: CGFloat = 33.0 / 28.0

    private var pink: Color { HabitCategory.mindfulness.style.baseColor }

    var body: some View {
        BlockSurface(
            cornerRadius: GridConstants.blockCornerRadius(forCell: side),
            scale: side / GridConstants.blockReferenceCell
        ) {
            pink
        }
        .frame(width: side, height: side)
        .overlay {
            Image("StrataSMark")
                .renderingMode(.template)
                .resizable()
                .scaledToFit()
                .frame(width: side * Self.capRatio * Self.aspect,
                       height: side * Self.capRatio)
                .foregroundStyle(.white)
                // Optically centred, not geometrically. The frosted band sits
                // across the bottom 26% of a block, so a letter on the exact
                // centre line has more clear field above it than below and
                // reads as having slipped down.
                .offset(y: -side * 0.02)
        }
        .accessibilityElement()
        .accessibilityLabel("Strata")
    }
}
